import type { WfrpActor } from "../../../types/foundry";
import { getChosenPatron } from "./actor-state";
import {
  activeMutationNamed,
  activeMutations,
  currentCareerGroup,
  hasEligibleAdditionalLegs,
  hasResolvedAdditionalArms,
  hasResolvedSelection,
  hasTalent,
  normalizeName,
  resolvedSelections,
  selectionValues,
} from "./document-helpers";
import type { MutationAcquisitionBlock, ResolvedMutation } from "./document-types";

const ALWAYS_LEG_ALTERING_MUTATIONS = new Set([
  "bachtrachian suckers",
  "bestial legs",
  "centauroid",
  "clubfoot",
  "hopper",
  "prehensile feet",
  "unnatural legs",
]);

interface HandAvailability {
  ambiguous: boolean;
  extraArms: boolean;
  primaryHands: Set<"left" | "right">;
}

function ordinaryHandAvailability(actor: WfrpActor, ignoreItemId?: string): HandAvailability {
  const primaryHands = new Set<"left" | "right">(["left", "right"]);
  let ambiguous = false;
  for (const item of activeMutations(actor, ignoreItemId)) {
    const name = normalizeName(item.name);
    const selections = resolvedSelections(item);
    if (name === "razor-sharp claws") primaryHands.clear();
    if (name === "pincer claw") {
      const hands = selectionValues(selections?.["pincer-hand"]);
      if (hands.length === 0) ambiguous = true;
      for (const hand of hands) {
        if (hand === "left" || hand === "right") primaryHands.delete(hand);
      }
    }
    if (name === "beweaponed extremities") {
      const arms = selectionValues(selections?.["arms"]);
      if (arms.includes("both")) primaryHands.clear();
      else if (arms.includes("one")) {
        const sides = selectionValues(selections?.["weapon-side"]);
        if (sides.length === 0) ambiguous = true;
        for (const side of sides) {
          if (side === "left" || side === "right") primaryHands.delete(side);
        }
      } else {
        ambiguous = true;
      }
    }
    if (name === "atrophy" && hasResolvedSelection(item, "atrophied-part", ["arm", "hand"])) {
      const sides = selectionValues(selections?.["atrophy-side"]);
      if (sides.length === 0) ambiguous = true;
      for (const side of sides) {
        if (side === "left" || side === "right") primaryHands.delete(side);
      }
    }
  }
  return {
    ambiguous,
    extraArms: hasResolvedAdditionalArms(actor, ignoreItemId),
    primaryHands,
  };
}

function priorSelection(
  actor: WfrpActor,
  mutationName: string,
  key: string,
  values: readonly string[],
  ignoreItemId?: string,
): boolean {
  return activeMutations(actor, ignoreItemId).some(
    (item) =>
      normalizeName(item.name) === normalizeName(mutationName) &&
      hasResolvedSelection(item, key, values),
  );
}

export function eligibilityBlock(message: string): MutationAcquisitionBlock {
  return { kind: "eligibility", message };
}

export function actorEligibilityBlocks(
  actor: WfrpActor,
  mutation: ResolvedMutation,
  ignoreItemId?: string,
): MutationAcquisitionBlock[] {
  const name = normalizeName(mutation.name);
  const blocks: MutationAcquisitionBlock[] = [];
  if (name === "chosen one" && hasTalent(actor, "Arcane Magic")) {
    blocks.push(eligibilityBlock(`${mutation.name} cannot be acquired with Arcane Magic.`));
  }
  if (name === "false wizard") {
    if (getChosenPatron(actor) === "khorne") {
      blocks.push(eligibilityBlock(`${mutation.name} cannot be acquired by a Chosen of Khorne.`));
    }
    const divineTalents = ["Bless", "Invoke"].filter((talent) => hasTalent(actor, talent));
    if (divineTalents.length > 0) {
      blocks.push(
        eligibilityBlock(`${mutation.name} cannot be acquired with ${divineTalents.join(" or ")}.`),
      );
    }
  }
  if (name === "malign sorcerer" && getChosenPatron(actor) === "khorne") {
    blocks.push(eligibilityBlock(`${mutation.name} cannot be acquired with Khorne as patron.`));
  }
  if (name === "prince of nothing") {
    const careerGroup = currentCareerGroup(actor);
    if (careerGroup === "noble") {
      blocks.push(eligibilityBlock(`${mutation.name} cannot be acquired by an actual Noble.`));
    } else if (careerGroup === undefined) {
      blocks.push(
        eligibilityBlock(
          `Confirm that ${actor.name} is not an actual Noble before acquiring ${mutation.name}.`,
        ),
      );
    }
  }
  if (name === "headless") {
    const elongated = activeMutationNamed(actor, "Elongated Limbs", ignoreItemId);
    if (elongated && hasResolvedSelection(elongated, "limb", ["neck"])) {
      blocks.push(
        eligibilityBlock(`${mutation.name} cannot be acquired with Elongated Limbs (Neck).`),
      );
    }
  }
  if (name === "wings" && priorSelection(actor, "Wings", "wing-size", ["huge"], ignoreItemId)) {
    blocks.push(
      eligibilityBlock(`${mutation.name} cannot be acquired again after reaching Huge wings.`),
    );
  }
  if (
    name === "beweaponed extremities" &&
    priorSelection(actor, "Beweaponed Extremities", "arms", ["both"], ignoreItemId)
  ) {
    blocks.push(
      eligibilityBlock(
        `${mutation.name} cannot be acquired again because a prior acquisition transformed both arms.`,
      ),
    );
  }
  if (name === "pincer claw" || name === "razor-sharp claws") {
    const hands = ordinaryHandAvailability(actor, ignoreItemId);
    if (hands.primaryHands.size === 0 && !hands.extraArms && !hands.ambiguous) {
      blocks.push(
        eligibilityBlock(`${mutation.name} requires at least one ordinary clawless hand.`),
      );
    } else if (hands.primaryHands.size === 0 || hands.extraArms || hands.ambiguous) {
      blocks.push(
        eligibilityBlock(
          `Confirm that ${actor.name} has an ordinary clawless hand that can receive ${mutation.name}; non-left/right or legacy hand anatomy cannot be inferred safely.`,
        ),
      );
    }
  }
  if (name === "overgrown arm" && hasResolvedAdditionalArms(actor, ignoreItemId)) {
    blocks.push(
      eligibilityBlock(
        `Confirm which arm receives ${mutation.name}; resolved extra arms are not limited to the tracked left/right choices.`,
      ),
    );
  }
  if (
    ALWAYS_LEG_ALTERING_MUTATIONS.has(name) &&
    activeMutationNamed(actor, "Blob", ignoreItemId) &&
    !hasEligibleAdditionalLegs(actor, ignoreItemId)
  ) {
    blocks.push(
      eligibilityBlock(
        `${mutation.name} alters legs, but ${actor.name} has Blob and no resolved Additional Extremities (Legs).`,
      ),
    );
  }
  return blocks;
}
