import type { MutationAcquisitionState } from "../../../../types/mutants-handbook";
import type { WfrpActor, WfrpMutationItem } from "../../../../types/foundry";
import { MODULE_ID } from "../../../constants";
import { MUTATION_RETIRED_FLAG, POSSESSION_REMOVED_FLAG } from "../constants";
import { readAcquisitionState, readMutationAutomation } from "./state";

export interface AcquisitionHistory {
  isLatest: boolean;
  occurrence: number;
  previousStates: MutationAcquisitionState[];
}

export function acquisitionHistory(
  actor: WfrpActor,
  item: WfrpMutationItem,
  definitionId: string,
): AcquisitionHistory {
  const matching = [...actor.items].filter((candidate) => {
    if (
      candidate.getFlag(MODULE_ID, POSSESSION_REMOVED_FLAG) === true ||
      candidate.getFlag(MODULE_ID, MUTATION_RETIRED_FLAG) === true
    ) {
      return false;
    }
    return readMutationAutomation(candidate)?.definitionId === definitionId;
  });
  const position = matching.findIndex((candidate) => candidate.id === item.id);
  const states = matching.flatMap((candidate, index) => {
    const state = readAcquisitionState(readMutationAutomation(candidate)?.state?.acquisition);
    return state?.status === "resolved" ? [{ index, state }] : [];
  });
  const ownState =
    position >= 0 ? states.find(({ index }) => index === position)?.state : undefined;
  const highestOccurrence = states.reduce(
    (highest, { state }) => Math.max(highest, state.occurrence),
    0,
  );
  const occurrence =
    ownState?.occurrence ??
    (position >= 0 ? position + 1 : Math.max(matching.length, highestOccurrence) + 1);
  const previousStates = states
    .filter(({ index, state }) =>
      ownState ? state.occurrence < occurrence : position < 0 || index < position,
    )
    .sort(
      (left, right) => left.state.occurrence - right.state.occurrence || left.index - right.index,
    )
    .map(({ state }) => state);
  return {
    isLatest: position < 0 || position === matching.length - 1,
    occurrence,
    previousStates,
  };
}
