import type { MutationAcquisitionRule } from "../../../../functions/mutants-handbook/automation/types";
import { resolveMutationNature } from "../../../../functions/mutants-handbook/rules";
import type {
  MutationAcquisitionBlockAudit,
  MutationAutomationDefinition,
} from "../../../../types/mutants-handbook";
import type { WfrpActor, WfrpMutationItem } from "../../../../types/foundry";
import { reconcileMutationAutomation } from "../automation/grant-reconciliation";
import { chooseMutationBlockAction } from "../dialogs";
import {
  getMutationAcquisitionBlockDetails,
  getResolvedMutationAcquisitionBlockDetails,
  isWfrpActor,
  type MutationAcquisitionBlock,
} from "../documents";
import { foundryAcquisitionServices, reviewResolvedAcquisition } from "./dialog";
import { preparePendingMutationDrop } from "../mutation-drop";
import { resolveMutationAcquisition } from "./resolve";
import { acquisitionHistory } from "./history";
import { acquisitionState, freshState, persistResolution, seedState } from "./persistence";
import {
  acceptedBlockMatches,
  isRecord,
  mergeAcceptedBlocks,
  readMutationAutomation,
} from "./state";

const BLOCK_LIMIT = 8;

function isMutationItem(value: unknown): value is WfrpMutationItem {
  if (!isRecord(value)) return false;
  return (
    value["type"] === "mutation" &&
    typeof value["id"] === "string" &&
    typeof value["name"] === "string" &&
    typeof value["getFlag"] === "function" &&
    typeof value["toObject"] === "function"
  );
}

function ownedBy(item: WfrpMutationItem, actor: WfrpActor): boolean {
  if (actor.items.has?.(item.id) === true) return true;
  return (
    actor.items.get?.(item.id) !== undefined || [...actor.items].some((entry) => entry === item)
  );
}

function optionBlocks(options: Record<string, unknown>): MutationAcquisitionBlockAudit[] {
  const value = options["mutationAcquisitionAcceptedBlocks"];
  return mergeAcceptedBlocks(Array.isArray(value) ? value : undefined);
}

function storeOptionBlocks(
  options: Record<string, unknown>,
  blocks: readonly MutationAcquisitionBlockAudit[],
): void {
  options["mutationAcquisitionAcceptedBlocks"] = [...blocks];
}

function abort(options: Record<string, unknown>, reroll = false): false {
  options["abortItemCreation"] = true;
  options["mutationAcquisitionCancelled"] = true;
  if (reroll) options["mutationAcquisitionRerollRequested"] = true;
  return false;
}

async function reviewBlocks(
  mutationName: string,
  details: readonly MutationAcquisitionBlock[],
  blocks: MutationAcquisitionBlockAudit[],
  options: Record<string, unknown>,
  canReroll: boolean,
): Promise<boolean> {
  for (const block of details) {
    if (acceptedBlockMatches(blocks, block)) continue;
    const action = await chooseMutationBlockAction(mutationName, block, canReroll);
    if (action === "reroll") return abort(options, true);
    if (action !== "accept") return abort(options);
    blocks.splice(0, blocks.length, ...mergeAcceptedBlocks(blocks, [block]));
    storeOptionBlocks(options, blocks);
  }
  return true;
}

async function reviewStaticBlocks(
  actor: WfrpActor,
  item: WfrpMutationItem,
  automation: MutationAutomationDefinition,
  owned: boolean,
  blocks: MutationAcquisitionBlockAudit[],
  options: Record<string, unknown>,
): Promise<boolean> {
  const nature = resolveMutationNature(item.system.mutationType.value);
  if (!nature) throw new Error(`${item.name} has no physical or mental mutation classification.`);
  const details = getMutationAcquisitionBlockDetails(
    actor,
    {
      acquisition: automation.acquisition as MutationAcquisitionRule,
      data: item.toObject(),
      name: item.name,
      nature,
    },
    owned ? item.id : undefined,
  );
  return reviewBlocks(
    item.name,
    details,
    blocks,
    options,
    options["mutationAcquisitionCanReroll"] === true,
  );
}

export async function prepareMutationAcquisition(
  itemValue: unknown,
  actorValue: unknown,
  options: Record<string, unknown>,
): Promise<boolean> {
  if (options["skipMutationAcquisition"] === true) return true;
  if (!isMutationItem(itemValue)) return true;
  const actor = isWfrpActor(actorValue)
    ? actorValue
    : isWfrpActor(itemValue.actor)
      ? itemValue.actor
      : undefined;
  if (!actor) return true;
  if (!(await preparePendingMutationDrop(itemValue, actor, options))) return false;
  const automation = readMutationAutomation(itemValue);
  if (!automation) return true;
  const owned = ownedBy(itemValue, actor);
  const oldState = acquisitionState(automation);
  const reconfigure = options["mutationAcquisitionReconfigure"] === true;
  const history = acquisitionHistory(actor, itemValue, automation.definitionId);
  if (reconfigure && owned && !history.isLatest) {
    ui.notifications.warn(
      `${itemValue.name}: only the latest active occurrence can be reconfigured because later results depend on its retained history.`,
    );
    return false;
  }
  const occurrence = history.occurrence;
  const blocks = mergeAcceptedBlocks(oldState?.acceptedBlocks, optionBlocks(options));
  storeOptionBlocks(options, blocks);
  if (!(await reviewStaticBlocks(actor, itemValue, automation, owned, blocks, options)))
    return false;

  let initial = reconfigure ? freshState(occurrence, blocks) : oldState;
  initial ??= seedState(automation, occurrence, blocks);
  const announcements: (() => Promise<void>)[] = [];
  for (let review = 0; review < BLOCK_LIMIT; review += 1) {
    const resolution = await resolveMutationAcquisition(
      {
        acceptedBlocks: blocks,
        facts: {
          actor: { name: actor.name, system: actor.system, type: actor.type },
          mutation: { name: itemValue.name, nature: itemValue.system.mutationType.value },
        },
        ...(initial ? { initialState: initial } : {}),
        mutationName: itemValue.name,
        occurrence,
        previousStates: history.previousStates,
        retainedRolls: automation.retainedRolls ?? [],
        steps: automation.acquisition.steps ?? [],
      },
      foundryAcquisitionServices,
    );
    if (resolution.status === "cancelled") return abort(options);
    announcements.push(...resolution.announcements);
    if (resolution.status === "blocked") {
      const action = await chooseMutationBlockAction(
        itemValue.name,
        resolution.block,
        options["mutationAcquisitionCanReroll"] === true,
      );
      if (action === "reroll") return abort(options, true);
      if (action !== "accept") return abort(options);
      blocks.splice(0, blocks.length, ...mergeAcceptedBlocks(blocks, [resolution.block]));
      storeOptionBlocks(options, blocks);
      initial = { ...resolution.state, acceptedBlocks: [...blocks] };
      continue;
    }
    const resolvedDetails = getResolvedMutationAcquisitionBlockDetails(
      actor,
      itemValue.name,
      resolution.state,
      owned ? itemValue.id : undefined,
    );
    if (
      !(await reviewBlocks(
        itemValue.name,
        resolvedDetails,
        blocks,
        options,
        options["mutationAcquisitionCanReroll"] === true,
      ))
    ) {
      return false;
    }
    const acceptedResolution = {
      ...resolution,
      state: { ...resolution.state, acceptedBlocks: [...blocks] },
    };
    await persistResolution(
      itemValue,
      automation,
      acceptedResolution,
      owned,
      reconfigure,
      oldState,
      options,
    );
    for (const announce of announcements) await announce();
    return true;
  }
  throw new Error(`Acquisition review for ${itemValue.name} exceeded its safe limit.`);
}

export async function resolveOwnedMutationAcquisition(itemUuid: string): Promise<boolean> {
  const item = await fromUuid(itemUuid);
  if (!isMutationItem(item) || !isWfrpActor(item.actor)) {
    throw new Error(`The UUID ${itemUuid} does not resolve to an owned mutation Item.`);
  }
  const automation = readMutationAutomation(item);
  if (!automation) throw new Error(`${item.name} has no Mutant's Handbook automation data.`);
  const stored = acquisitionState(automation);
  if (stored?.status === "resolved") {
    const decision = await reviewResolvedAcquisition(item.name, stored);
    if (decision === "keep") return true;
  }
  const options: Record<string, unknown> = {
    ...(stored?.status === "resolved" ? { mutationAcquisitionReconfigure: true } : {}),
  };
  const resolved = await prepareMutationAcquisition(item, item.actor, options);
  if (resolved) await reconcileMutationAutomation(item.actor.uuid);
  return resolved;
}
