import type { MutationAcquisitionBlockAudit } from "../../../../types/mutants-handbook";

export const CANCELLED = Symbol("acquisition-cancelled");
export const LIMITS = { depth: 8, resolutions: 32, tableRolls: 20 } as const;

export class AcquisitionBlocked {
  constructor(readonly block: MutationAcquisitionBlockAudit) {}
}

export function createAcquisitionBlock(
  mutationName: string,
  prompt: string,
  kind: MutationAcquisitionBlockAudit["kind"],
  detail: string,
): MutationAcquisitionBlockAudit {
  return { kind, message: `${mutationName}: ${prompt} ${detail}.` };
}
