import type {
  MutationAcquisitionBlockAudit,
  MutationAcquisitionState,
  MutationAutomationDefinition,
  MutationCharacteristicKey,
  MutationModifier,
} from "../../../../types/mutants-handbook";
import type { WfrpMutationItem } from "../../../../types/foundry";
import { MODULE_ID } from "../../../constants";

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

const CHARACTERISTICS = new Set<MutationCharacteristicKey>([
  "ag",
  "bs",
  "dex",
  "fel",
  "i",
  "int",
  "s",
  "t",
  "wp",
  "ws",
]);
const MULTIPLIER_ROUNDS = new Set(["ceil", "floor", "round"]);

function hasOnlyKeys(value: Record<string, unknown>, allowed: readonly string[]): boolean {
  const keys = new Set(allowed);
  return Object.keys(value).every((key) => keys.has(key));
}

function validKey(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0 && value.length <= 256;
}

function finiteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

function validCharacteristic(value: unknown): value is MutationCharacteristicKey {
  return typeof value === "string" && CHARACTERISTICS.has(value as MutationCharacteristicKey);
}

function validScope(value: unknown): value is "first" | undefined {
  return value === undefined || value === "first";
}

function validRollOrValue(value: Record<string, unknown>): boolean {
  const roll = value["roll"];
  const hasRoll = typeof roll === "string" && roll.trim().length > 0;
  const hasValue = finiteNumber(value["value"]);
  return hasRoll !== hasValue;
}

function validSkills(value: unknown): value is string[] | undefined {
  return (
    value === undefined ||
    (Array.isArray(value) &&
      value.every((entry) => typeof entry === "string" && entry.trim().length > 0))
  );
}

function validCharacteristics(value: unknown): value is MutationCharacteristicKey[] | undefined {
  return value === undefined || (Array.isArray(value) && value.every(validCharacteristic));
}

export function sanitizeMutationModifier(value: unknown): MutationModifier | undefined {
  if (!isRecord(value) || !validKey(value["key"]) || typeof value["kind"] !== "string") {
    return undefined;
  }

  const key = value["key"];
  switch (value["kind"]) {
    case "characteristic": {
      if (
        !hasOnlyKeys(value, ["characteristic", "key", "kind", "roll", "scope", "value"]) ||
        !validCharacteristic(value["characteristic"]) ||
        !validScope(value["scope"]) ||
        !validRollOrValue(value)
      ) {
        return undefined;
      }
      return {
        characteristic: value["characteristic"],
        key,
        kind: "characteristic",
        ...(typeof value["roll"] === "string" ? { roll: value["roll"] } : {}),
        ...(value["scope"] === "first" ? { scope: "first" as const } : {}),
        ...(finiteNumber(value["value"]) ? { value: value["value"] } : {}),
      };
    }
    case "characteristicCap":
      if (
        !hasOnlyKeys(value, ["characteristic", "key", "kind", "maximum"]) ||
        !validCharacteristic(value["characteristic"]) ||
        !finiteNumber(value["maximum"]) ||
        value["maximum"] < 0
      ) {
        return undefined;
      }
      return {
        characteristic: value["characteristic"],
        key,
        kind: "characteristicCap",
        maximum: value["maximum"],
      };
    case "move":
    case "status":
      if (
        !hasOnlyKeys(value, ["key", "kind", "scope", "value"]) ||
        !validScope(value["scope"]) ||
        !finiteNumber(value["value"])
      ) {
        return undefined;
      }
      return {
        key,
        kind: value["kind"],
        ...(value["scope"] === "first" ? { scope: "first" as const } : {}),
        value: value["value"],
      };
    case "moveMultiplier":
      if (
        !hasOnlyKeys(value, ["key", "kind", "round", "value"]) ||
        typeof value["round"] !== "string" ||
        !MULTIPLIER_ROUNDS.has(value["round"]) ||
        !finiteNumber(value["value"])
      ) {
        return undefined;
      }
      return {
        key,
        kind: "moveMultiplier",
        round: value["round"] as "ceil" | "floor" | "round",
        value: value["value"],
      };
    case "sizeStep":
      if (
        !hasOnlyKeys(value, ["direction", "key", "kind"]) ||
        (value["direction"] !== -1 && value["direction"] !== 1)
      ) {
        return undefined;
      }
      return { direction: value["direction"], key, kind: "sizeStep" };
    case "test": {
      const skills = value["skills"];
      const characteristics = value["characteristics"];
      if (
        !hasOnlyKeys(value, ["characteristics", "key", "kind", "roll", "skills", "value"]) ||
        !validSkills(skills) ||
        !validCharacteristics(characteristics) ||
        !(skills?.length || characteristics?.length) ||
        !validRollOrValue(value)
      ) {
        return undefined;
      }
      return {
        ...(characteristics ? { characteristics: [...characteristics] } : {}),
        key,
        kind: "test",
        ...(typeof value["roll"] === "string" ? { roll: value["roll"] } : {}),
        ...(skills ? { skills: [...skills] } : {}),
        ...(finiteNumber(value["value"]) ? { value: value["value"] } : {}),
      };
    }
    case "wounds":
      if (!hasOnlyKeys(value, ["key", "kind", "value"]) || !finiteNumber(value["value"])) {
        return undefined;
      }
      return { key, kind: "wounds", value: value["value"] };
    default:
      return undefined;
  }
}

function isBlock(value: unknown): value is MutationAcquisitionBlockAudit {
  if (!isRecord(value) || typeof value["message"] !== "string") return false;
  return ["conflict", "eligibility", "exhausted", "maximum"].includes(String(value["kind"]));
}

export function mergeAcceptedBlocks(
  ...sources: readonly (readonly unknown[] | undefined)[]
): MutationAcquisitionBlockAudit[] {
  const blocks = sources.flatMap((source) => source ?? []).filter(isBlock);
  return blocks.filter(
    (block, index) =>
      blocks.findIndex(
        (candidate) => candidate.kind === block.kind && candidate.message === block.message,
      ) === index,
  );
}

function validValues(
  value: unknown,
  scalar: "number" | "string",
): value is Record<string, number | number[] | string | string[]> {
  if (!isRecord(value)) return false;
  const valid = (entry: unknown) =>
    typeof entry === scalar && (scalar !== "number" || Number.isFinite(entry));
  return Object.values(value).every(
    (entry) => valid(entry) || (Array.isArray(entry) && entry.every(valid)),
  );
}

export function readAcquisitionState(value: unknown): MutationAcquisitionState | undefined {
  if (!isRecord(value) || value["version"] !== 1) return undefined;
  if (value["status"] !== "pending" && value["status"] !== "resolved") return undefined;
  if (!Number.isSafeInteger(value["occurrence"]) || Number(value["occurrence"]) < 1) {
    return undefined;
  }
  if (!validValues(value["rolls"], "number") || !validValues(value["selections"], "string")) {
    return undefined;
  }
  if (!Array.isArray(value["grants"])) return undefined;
  const modifiers = Array.isArray(value["modifiers"])
    ? value["modifiers"]
        .map(sanitizeMutationModifier)
        .filter((modifier): modifier is MutationModifier => modifier !== undefined)
    : [];
  return {
    acceptedBlocks: mergeAcceptedBlocks(
      Array.isArray(value["acceptedBlocks"]) ? value["acceptedBlocks"] : undefined,
    ),
    grants: value["grants"] as MutationAcquisitionState["grants"],
    modifiers,
    occurrence: Number(value["occurrence"]),
    rolls: value["rolls"] as MutationAcquisitionState["rolls"],
    selections: value["selections"] as MutationAcquisitionState["selections"],
    status: value["status"],
    version: 1,
  };
}

export function readMutationAutomation(
  item: WfrpMutationItem,
): MutationAutomationDefinition | undefined {
  const value = item.getFlag(MODULE_ID, "mutationAutomation");
  return isRecord(value) && isRecord(value["acquisition"])
    ? (value as unknown as MutationAutomationDefinition)
    : undefined;
}

export function acceptedBlockMatches(
  blocks: readonly MutationAcquisitionBlockAudit[],
  block: MutationAcquisitionBlockAudit,
): boolean {
  return blocks.some(
    (candidate) => candidate.kind === block.kind && candidate.message === block.message,
  );
}
