import type {
  MutationAcquisitionState,
  MutationAcquisitionStep,
} from "../../../../types/mutants-handbook";

export function repeatEligibilityDetail(
  step: MutationAcquisitionStep,
  occurrence: number,
  previous: readonly MutationAcquisitionState[],
): string | undefined {
  if (occurrence <= 1) return undefined;
  if (step.repeat === "copy-first" && !previous.some((state) => state.occurrence === 1)) {
    return "cannot copy because the first occurrence has no resolved result";
  }
  if (step.repeat === "unique") {
    const resolved = new Set(previous.map((state) => state.occurrence));
    for (let expected = 1; expected < occurrence; expected += 1) {
      if (!resolved.has(expected)) {
        return `cannot guarantee a unique result because occurrence ${expected} is unresolved`;
      }
    }
  }
  return undefined;
}
