import type {
  MutationAcquisitionBlockAudit,
  MutationAcquisitionState,
  MutationAutomationDefinition,
} from "../../../../types/mutants-handbook";
import type { WfrpMutationItem } from "../../../../types/foundry";
import { MODULE_ID } from "../../../constants";
import { isRecord, readAcquisitionState } from "./state";
import type { AcquisitionResolution } from "./types";

function numericRolls(value: unknown): Record<string, number> {
  if (!isRecord(value)) return {};
  return Object.fromEntries(
    Object.entries(value).filter((entry): entry is [string, number] => Number.isFinite(entry[1])),
  );
}

function previousOwnedRollKeys(state: MutationAcquisitionState | undefined): Set<string> {
  return new Set(state?.modifiers.map((modifier) => modifier.key) ?? []);
}

export function acquisitionState(
  automation: MutationAutomationDefinition,
): MutationAcquisitionState | undefined {
  return readAcquisitionState(automation.state?.acquisition);
}

export function seedState(
  automation: MutationAutomationDefinition,
  occurrence: number,
  blocks: readonly MutationAcquisitionBlockAudit[],
): MutationAcquisitionState | undefined {
  const rolls = numericRolls(automation.state?.rolls);
  const retained = Object.fromEntries(
    (automation.retainedRolls ?? [])
      .filter((entry) => typeof rolls[entry.key] === "number")
      .map((entry) => [entry.key, rolls[entry.key] as number]),
  );
  if (Object.keys(retained).length === 0 && blocks.length === 0) return undefined;
  return {
    acceptedBlocks: [...blocks],
    grants: [],
    modifiers: [],
    occurrence,
    rolls: retained,
    selections: {},
    status: "pending",
    version: 1,
  };
}

export function freshState(
  occurrence: number,
  blocks: readonly MutationAcquisitionBlockAudit[],
): MutationAcquisitionState {
  return {
    acceptedBlocks: [...blocks],
    grants: [],
    modifiers: [],
    occurrence,
    rolls: {},
    selections: {},
    status: "pending",
    version: 1,
  };
}

export async function persistResolution(
  item: WfrpMutationItem,
  automation: MutationAutomationDefinition,
  resolution: Extract<AcquisitionResolution, { status: "resolved" }>,
  owned: boolean,
  reconfigure: boolean,
  oldState: MutationAcquisitionState | undefined,
  options: Record<string, unknown>,
): Promise<void> {
  const state = isRecord(automation.state) ? { ...automation.state } : {};
  const rolls = numericRolls(state["rolls"]);
  if (reconfigure) {
    const oldKeys = previousOwnedRollKeys(oldState);
    for (const retained of automation.retainedRolls ?? []) oldKeys.add(retained.key);
    for (const key of oldKeys) delete rolls[key];
  }
  const nextState = {
    ...state,
    acquisition: resolution.state,
    rolls: { ...rolls, ...resolution.retainedRolls },
  };
  const changes = { [`flags.${MODULE_ID}.mutationAutomation.state`]: nextState };
  if (!owned) {
    if (!item.updateSource)
      throw new Error(`Foundry cannot stage acquisition state for ${item.name}.`);
    item.updateSource(changes);
    return;
  }
  if (!item.update) throw new Error(`Foundry cannot update acquisition state for ${item.name}.`);
  await item.update(changes, options);
}
